template <class F> class scope_exit {
    F f_; bool active_ = true;
public:
    explicit scope_exit(F f) : f_(std::move(f)) {}
    void release() noexcept { active_ = false; }
    ~scope_exit() { if (active_) f_(); }
};
// attach the action where the resource is acquired
auto guard = scope_exit([&]{ tx.rollback_if_not_committed(); });
operate(tx);
tx.commit();
guard.release();          // commit done: the guard no longer runs

