#include <experimental/scope>
void save(std::ofstream &out, const std::string &path) {
    auto remove_partial = std::experimental::scope_fail{
        [&]{ out.close(); std::remove(path.c_str()); }};
    write_all(out);             // throws -> the partial file is removed
    out.close();
    remove_partial.release();   // committed: keep the file
}

body.open(path, std::ios::out | std::ios::trunc);
bool committed = false;
BOOST_SCOPE_EXIT(&body, &path, &committed) {
    body.close();
    if (!committed) std::remove(path.c_str());   // undo on any exit path
} BOOST_SCOPE_EXIT_END
write_all(body);
committed = true;
